+				offset += 4;
+
+				proto_tree_add_item(subtree, hf_egfx_cap_length, tvb, offset, 4, ENC_LITTLE_ENDIAN);
+				capsDataLength = tvb_get_guint32(tvb, offset, ENC_LITTLE_ENDIAN);
+				offset += 4;
+
+				offset += capsDataLength;
+			}
+			break;
+		}
