+	if (nbits > b->remainingBits) {
+		*ok = FALSE;
+		return 0;
+	}
+
+	while (b->currentBits < nbits) {
+		if (!tvb_reported_length_remaining(b->input, b->offset)) {
+			*ok = FALSE;
+			return 0;
+		}
