+		b->currentValue <<= 8;
+		b->currentValue += tvb_get_guint8(b->input, b->offset++);
+
+		b->currentBits += 8;
+	}
+
+	*ok = TRUE;
+	ret = b->currentValue >> (b->currentBits-nbits);
+	b->currentBits -= nbits;
+	b->remainingBits -= nbits;
+	b->currentValue &= (1 << b->currentBits) - 1;
+
+	return ret;
